#include <cstdio>
#include <iostream>
#include <sys/mman.h>
#include <unistd.h>
int main() {
    FILE* file = std::tmpfile();
    if (!file) return 1;
    const unsigned char data[3]{3, 5, 7};
    if (std::fwrite(data, 1, 3, file) != 3 || std::fflush(file) != 0) {
        std::fclose(file); return 1;
    }
    void* region = mmap(nullptr, 3, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    const bool closed = std::fclose(file) == 0;
    if (region == MAP_FAILED) return 1;
    if (!closed) { munmap(region, 3); return 1; }
    const auto* bytes = static_cast<const unsigned char*>(region);
    unsigned sum = 0;
    for (unsigned i = 0; i < 3; ++i) sum += bytes[i];
    if (munmap(region, 3) != 0) return 1;
    std::cout << "mapped sum after close=" << sum << '\n';
}

#include <cstdio>
#include <iostream>
#include <sys/mman.h>
#include <unistd.h>
int main() {
    FILE* file = std::tmpfile();
    if (!file) return 1;
    const unsigned char initial = 4;
    if (std::fwrite(&initial, 1, 1, file) != 1 || std::fflush(file) != 0) {
        std::fclose(file); return 1;
    }
    void* region = mmap(nullptr, 1, PROT_READ | PROT_WRITE,
                        MAP_PRIVATE, fileno(file), 0);
    if (region == MAP_FAILED) { std::fclose(file); return 1; }
    auto* byte = static_cast<unsigned char*>(region);
    *byte = 9;
    const unsigned observed = *byte;
    unsigned char backing = 0;
    bool okay = pread(fileno(file), &backing, 1, 0) == 1;
    okay = munmap(region, 1) == 0 && okay;
    okay = std::fclose(file) == 0 && okay;
    if (!okay) return 1;
    std::cout << "private=" << observed << " backing="
              << static_cast<unsigned>(backing) << '\n';
}
